function generateRules(frequentItemsets, minConfidence) {
  const compareStocks = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
  const itemsets = new Map();
  for (const itemset of frequentItemsets) {
    const items = [...new Set(itemset.items.map(stockOf))].sort(compareStocks);
    itemsets.set(JSON.stringify(items), { ...itemset, items });
  }
  const counts = new Map(
    [...itemsets].map(([key, itemset]) => [key, itemset.count]),
  );
  const rules = [];

  for (const itemset of itemsets.values()) {
    if (itemset.items.length < 2) continue;

    // Putting each stock on either side visits A -> B and B -> A separately.
    function split(position, antecedent, consequent) {
      if (position === itemset.items.length) {
        if (antecedent.length === 0 || consequent.length === 0) return;
        const antecedentCount = counts.get(JSON.stringify(antecedent));
        const consequentCount = counts.get(JSON.stringify(consequent));
        if (!antecedentCount || !consequentCount) return;
        const confidence = itemset.count / antecedentCount;
        if (confidence >= minConfidence) {
          rules.push({
            antecedent: [...antecedent],
            consequent: [...consequent],
            jointCount: itemset.count,
            antecedentCount,
            consequentCount,
            support: itemset.support,
            confidence,
          });
        }
        return;
      }

      const stock = itemset.items[position];
      antecedent.push(stock);
      split(position + 1, antecedent, consequent);
      antecedent.pop();
      consequent.push(stock);
      split(position + 1, antecedent, consequent);
      consequent.pop();
    }
    split(0, [], []);
  }
  return rules;
}

// ---------------------------------------------------------------------------
// Tiny worked example (used by the automated tests and the readout panel)
// ---------------------------------------------------------------------------

/**
 * A five-basket fixture with hand-computed support / confidence / lift values.
 *
 * The fixture is deliberately small enough to check with a pencil:
 *
 *   T1: bread, milk, jam, ham
 *   T2: bread, milk, jam
 *   T3: bread, milk
 *   T4: bread, jam, eggs
 *   T5: bread, eggs
 *
 * Item counts: bread = 5, milk = 3, jam = 3, eggs = 2, ham = 1 (N = 5).
 *
 * Because `bread` appears in every basket, every rule with `bread` on either
 * side has lift exactly 1 — that is the teaching point of the fixture.
 *
 * @returns {{n: number, baskets: string[][], itemCounts: Object<string, number>, rules: Array<Object>}}
 */

