#!/usr/bin/env python3
"""Preflight an LLM4Rec report PDF and authentic session export.

This script checks deterministic structure and file integrity. It cannot prove
that citations, reasoning, results, or claims of personal verification are true;
those require the manual evidence checklist.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path
from typing import Iterable


REQUIRED_HEADINGS = {
    "Abstract": r"(?im)^\s*abstract\s*$",
    "1. Introduction": r"(?im)^\s*(?:§\s*)?1\.?\s+introduction\s*$",
    "2. Related Work": r"(?im)^\s*(?:§\s*)?2\.?\s+related\s+work\s*$",
    "3. Method": r"(?im)^\s*(?:§\s*)?3\.?\s+method\s*$",
    "4. Experiments": r"(?im)^\s*(?:§\s*)?4\.?\s+experiments\s*$",
    "5. Discussion": r"(?im)^\s*(?:§\s*)?5\.?\s+discussion\s*$",
    "6. AI Usage Disclosure": (
        r"(?im)^\s*(?:§\s*)?6\.?\s+ai\s+usage\s+disclosure\s*$"
    ),
    "References": r"(?im)^\s*references\s*$",
}

DISCLOSURE_MARKERS = {
    "How AI was used": r"(?i)how\s+ai\s+was\s+used",
    "What I personally verified": r"(?i)what\s+i\s+personally\s+verified",
    "What I trusted without verification": (
        r"(?i)what\s+i\s+trusted\s+without\s+verification"
    ),
    "session.json reference": r"(?i)session\.json",
}

URL_RE = re.compile(r"https?://[^\s\]\)>]+", re.IGNORECASE)


def normalize_extracted_text(text: str) -> str:
    """Repair common ligatures and private-use glyphs emitted by Word PDFs."""
    replacements = {
        "\ufb00": "ff",
        "\ufb01": "fi",
        "\ufb02": "fl",
        "\ufb03": "ffi",
        "\ufb04": "ffl",
        "Ɵ": "ti",
        "Ʃ": "tt",
        "Ō": "ft",
    }
    for source, target in replacements.items():
        text = text.replace(source, target)
    return text


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Check deterministic LLM4Rec submission requirements."
    )
    parser.add_argument("report", type=Path, help="Path to the report PDF")
    parser.add_argument(
        "--session", type=Path, help="Path to the unmodified tool-native session JSON"
    )
    parser.add_argument(
        "--student-prefix",
        help="Filename prefix, for example ivanova_anna or team_alpha",
    )
    parser.add_argument(
        "--assignment",
        type=str.lower,
        choices=[f"a{i:02d}" for i in range(1, 11)],
        help="Assignment ID a01-a10",
    )
    parser.add_argument(
        "--body-page-limit",
        type=int,
        default=5,
        help="Maximum body pages excluding references (default: 5)",
    )
    return parser.parse_args()


def load_pdf(path: Path) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    try:
        from pypdf import PdfReader
    except ImportError:
        return [], [
            "pypdf is not installed; install it in the active Python environment "
            "before running this check"
        ]

    try:
        reader = PdfReader(str(path))
    except Exception as exc:  # pypdf exposes several parser-specific exceptions
        return [], [f"cannot open report PDF: {exc}"]

    if reader.is_encrypted:
        errors.append("report PDF is encrypted")
        try:
            if reader.decrypt("") == 0:
                return [], errors
        except Exception:
            return [], errors

    pages: list[str] = []
    for number, page in enumerate(reader.pages, start=1):
        try:
            pages.append(normalize_extracted_text(page.extract_text() or ""))
        except Exception as exc:
            errors.append(f"could not extract text from PDF page {number}: {exc}")
            pages.append("")
    return pages, errors


def find_reference_page(pages: Iterable[str]) -> int | None:
    for page_number, text in enumerate(pages, start=1):
        if re.search(REQUIRED_HEADINGS["References"], text):
            return page_number
    return None


def section_text(text: str, start_pattern: str, end_pattern: str) -> str | None:
    start = re.search(start_pattern, text)
    if not start:
        return None
    tail = text[start.end() :]
    end = re.search(end_pattern, tail)
    return tail[: end.start()] if end else tail


def count_sentences(text: str) -> int:
    compact = re.sub(r"\s+", " ", text).strip()
    if not compact:
        return 0
    return len(re.findall(r"[.!?](?=\s|$)", compact))


def validate_session(path: Path) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    warnings: list[str] = []

    if not path.exists():
        return [f"session file does not exist: {path}"], warnings
    if not path.is_file():
        return [f"session path is not a file: {path}"], warnings
    if path.stat().st_size == 0:
        return ["session file is empty"], warnings
    if path.suffix.lower() != ".json":
        warnings.append("session filename does not end in .json")
    if path.stat().st_size > 10 * 1024 * 1024:
        warnings.append(
            "session file exceeds 10 MB; the guidelines say to contact the instructor "
            "before submission"
        )

    try:
        raw = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return ["session file is not valid UTF-8 text"], warnings
    except OSError as exc:
        return [f"cannot read session file: {exc}"], warnings

    try:
        json.loads(raw)
        return errors, warnings
    except json.JSONDecodeError:
        pass

    lines = [line for line in raw.splitlines() if line.strip()]
    try:
        for line in lines:
            json.loads(line)
    except json.JSONDecodeError as exc:
        errors.append(
            "session file is neither one valid JSON value nor valid JSON Lines: "
            f"{exc}"
        )
    return errors, warnings


def main() -> int:
    args = parse_args()
    errors: list[str] = []
    warnings: list[str] = []

    if not args.report.exists():
        errors.append(f"report file does not exist: {args.report}")
        pages: list[str] = []
    elif not args.report.is_file():
        errors.append(f"report path is not a file: {args.report}")
        pages = []
    elif args.report.suffix.lower() != ".pdf":
        errors.append("report filename must end in .pdf")
        pages = []
    else:
        pages, pdf_errors = load_pdf(args.report)
        errors.extend(pdf_errors)

    if bool(args.student_prefix) != bool(args.assignment):
        warnings.append(
            "provide both --student-prefix and --assignment to check exact filenames"
        )
    elif args.student_prefix and args.assignment:
        expected_report = f"{args.student_prefix}_{args.assignment}_report.pdf"
        if args.report.name != expected_report:
            errors.append(
                f"report filename is {args.report.name!r}; expected {expected_report!r}"
            )
        if args.session:
            expected_session = f"{args.student_prefix}_{args.assignment}_session.json"
            if args.session.name != expected_session:
                errors.append(
                    f"session filename is {args.session.name!r}; "
                    f"expected {expected_session!r}"
                )

    full_text = "\n".join(pages)
    if pages:
        if not full_text.strip():
            errors.append("no extractable text found in the report PDF")

        for label, pattern in REQUIRED_HEADINGS.items():
            if not re.search(pattern, full_text):
                errors.append(f"required heading not found: {label}")

        reference_page = find_reference_page(pages)
        if reference_page is None:
            body_pages = len(pages)
            warnings.append(
                "could not locate a standalone References heading; counted every page "
                "against the body-page limit"
            )
        else:
            body_pages = reference_page - 1

